SELECT count(*) num,
from_unixtime(round(access_time / 1000), '%m-%d') AS time
FROM sys_access_history


        AND access_time BETWEEN #{startTime} AND #{endTime}


        AND item_id = #{itemId}


        AND store_id = #{storeId}


GROUP BY time
ORDER BY access_time

SELECT count(*) num
FROM sys_access_history


        AND access_time BETWEEN #{startTime} AND #{endTime}


        AND item_id = #{itemId}


        AND store_id = #{storeId}

SELECT
count( DISTINCT ( access_client_id ) ) AS num,
from_unixtime(round(access_time / 1000), '%m-%d') AS time
FROM sys_access_history


        AND access_time BETWEEN #{startTime} AND #{endTime}


        AND item_id = #{itemId}


        AND store_id = #{storeId}


GROUP BY time
ORDER BY access_time

SELECT count(DISTINCT ( access_client_id )) num
FROM sys_access_history


        AND access_time BETWEEN #{startTime} AND #{endTime}


        AND item_id = #{itemId}


        AND store_id = #{storeId}

SELECT count(*) num, from_unixtime(round(access_time / 1000), '%m-%d') AS time FROM sys_access_history
AND access_time BETWEEN #{startTime} AND #{endTime}
GROUP BY time ORDER BY access_time

SELECT ash.item_id,ppi.item_name,ppi.product_id,ppi.item_unit_price,ppb.product_name, COUNT(*) AS num FROM sys_access_history ash INNER JOIN pt_product_item ppi on ash.item_id = ppi.item_id INNER JOIN pt_product_base ppb on ppi.product_id = ppb.product_id
AND ash.access_time BETWEEN #{params.stime} AND #{params.etime}
AND ash.item_id = #{params.itemId}
AND ash.store_id = #{params.storeId}
GROUP BY ash.item_id ORDER BY num DESC LIMIT 0, 100
